// 上层统一复核原权源及真实提交史，低层writer仍各自只写唯一拥有的业务记录。
#include "political_succession_business.hpp"
namespace hanmo::resident {
Status validate_political_succession_sources(const PoliticalSuccessionContext& x){const auto& n=x.sources.nominations;if(x.state.version!=1||&n.state!=&x.state.nominations||n.accessions!=&x.state.accessions)return common_failure("PoliticalSuccessionCandidateMismatch");return validate_political_succession_accessions({x.sources,x.state.accessions});}
Status validate_political_successions(const PoliticalSuccessionContext& x){if(!x.result_match)return common_failure("PoliticalSuccessionResultReadRequired");auto valid=validate_political_succession_sources(x);return valid.ok?validate_political_succession_player_results(x.sources.nominations.common,x.state,x.result_match):valid;}
Outcome<PoliticalSuccessionQuote> preview_political_succession(const PoliticalSuccessionContext& x,const StableId& actor,const PoliticalSuccessionCommand& command){auto valid=validate_political_successions(x);if(!valid.ok)return {false,{},valid.error};return std::visit([&](const auto& c)->Outcome<PoliticalSuccessionQuote>{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PoliticalAccedeSuccession>){auto q=preview_political_succession_accession({x.sources,x.state.accessions},actor,c);if(!q.ok)return {false,{},q.error};return {true,{q.value.identity,actor,command,std::move(q.value)},{}};}else{auto q=preview_political_succession_nomination(x.sources.nominations,actor,PoliticalSuccessionNominationCommand{c});if(!q.ok)return {false,{},q.error};return {true,{q.value.identity,actor,command,std::move(q.value)},{}};}},command);}
// 正式写入前沿相同候选重新预览；外部quote不能替换原authority、原接受或本次文书。
Outcome<PoliticalSuccessionEffects> apply_political_succession_in_candidate(CommonStore& common,OrganizationState& organizations,PoliticalSuccessionState& state,const PoliticalSuccessionContext& x,const StableId& actor,const PoliticalSuccessionCommand& command,const PoliticalSuccessionQuote& quote){const auto& a=common.state().identity;const auto& b=quote.identity;if(&common!=&x.sources.nominations.common||&organizations!=&x.sources.nominations.organizations||&state!=&x.state||actor!=quote.actor_id||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick)||!compare_boundary(encode_political_succession_command(command),encode_political_succession_command(quote.command)).exact()||command.index()!=quote.command.index())return {false,{},common_failure("StalePoliticalSuccessionQuote").error};auto fresh=preview_political_succession(x,actor,command);if(!fresh.ok)return {false,{},fresh.error};return std::visit([&](const auto& c)->Outcome<PoliticalSuccessionEffects>{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PoliticalAccedeSuccession>){auto id=apply_political_succession_accession_in_candidate(common,organizations,state.accessions,{x.sources,state.accessions},actor,c,std::get<PoliticalSuccessionAccessionQuote>(fresh.value.details));if(!id.ok)return {false,{},id.error};const auto* record=state.accessions.accessions.find(id.value);if(!record)return {false,{},common_failure("PoliticalSuccessionAccessionSourceRequired",id.value).error};return {true,{id.value,record->office_change_fact_id},{}};}else{auto id=apply_political_succession_nomination_in_candidate(common,state.nominations,x.sources.nominations,actor,PoliticalSuccessionNominationCommand{c},std::get<PoliticalSuccessionNominationQuote>(fresh.value.details));return id.ok?Outcome<PoliticalSuccessionEffects>{true,{id.value,{}},{}}:Outcome<PoliticalSuccessionEffects>{false,{},id.error};}},command);}
}
